// Package docs generates the reference pages under docs/ from the packages.
package docs

import (
	"encoding/json"
	"fmt"
	"path"
	"strings"

	"github.com/fuseone-io/fusescope-integrations/pkg/integration"
)

// Header marks generated files; the check compares whole files.
const Header = "<!-- Generated by `go run ./cmd/fsint docs`. Do not edit. -->\n\n"

// Generate returns the docs tree: file name relative to docs/ → content.
func Generate(pkgs []*integration.Package) (map[string]string, error) {
	files := map[string]string{}

	var index strings.Builder
	index.WriteString(Header)
	index.WriteString("# Integrations\n\n")
	index.WriteString("| Integration | Id | Version | FuseScope | Signals | Dashboards |\n")
	index.WriteString("|---|---|---|---|---|---|\n")

	for _, p := range pkgs {
		d, err := integration.Render(p)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", p.Dir, err)
		}
		m := p.Manifest
		page := p.Dir + ".md"
		fmt.Fprintf(&index, "| [%s](integrations/%s) | `%s` | %s | `%s` | %s | %d |\n",
			m.Title, page, m.ID, m.Version, m.FuseScope, strings.Join(m.Signals, ", "), len(m.Assets.Dashboards))

		content, err := packagePage(p, d)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", p.Dir, err)
		}
		files[path.Join("integrations", page)] = content
	}
	files["README.md"] = index.String()
	return files, nil
}

func packagePage(p *integration.Package, d *integration.Details) (string, error) {
	m := p.Manifest
	var b strings.Builder
	b.WriteString(Header)
	fmt.Fprintf(&b, "# %s\n\n%s\n\n", m.Title, m.Description)
	b.WriteString("| | |\n|---|---|\n")
	fmt.Fprintf(&b, "| Id | `%s` |\n", m.ID)
	fmt.Fprintf(&b, "| Version | %s |\n", m.Version)
	fmt.Fprintf(&b, "| FuseScope | `%s` |\n", m.FuseScope)
	fmt.Fprintf(&b, "| Categories | %s |\n", strings.Join(m.Categories, ", "))
	fmt.Fprintf(&b, "| Signals | %s |\n", strings.Join(m.Signals, ", "))
	fmt.Fprintf(&b, "| Source | [`integrations/%s/`](../../integrations/%s/) |\n\n", p.Dir, p.Dir)

	b.WriteString("## Configuration\n\n")
	for _, step := range m.Configuration {
		fmt.Fprintf(&b, "- [%s](../../integrations/%s/%s)\n", step.Title, p.Dir, step.Instructions)
	}

	if len(d.Assets.Dashboards) > 0 {
		b.WriteString("\n## Dashboards\n\n| Id | Name | Panels |\n|---|---|---|\n")
		for _, dash := range d.Assets.Dashboards {
			var def struct {
				Spec struct {
					Display struct {
						Name string `json:"name"`
					} `json:"display"`
					Panels map[string]json.RawMessage `json:"panels"`
				} `json:"spec"`
			}
			if err := json.Unmarshal(dash.Definition, &def); err != nil {
				return "", fmt.Errorf("dashboard %s: %w", dash.ID, err)
			}
			fmt.Fprintf(&b, "| `%s` | %s | %d |\n", dash.ID, escape(def.Spec.Display.Name), len(def.Spec.Panels))
		}
	}

	if len(d.DataCollected.Logs) > 0 {
		b.WriteString("\n## Log attributes\n\n| Name | Path | Type |\n|---|---|---|\n")
		for _, l := range d.DataCollected.Logs {
			fmt.Fprintf(&b, "| %s | `%s` | %s |\n", escape(l.Name), l.Path, l.Type)
		}
	}
	if len(d.DataCollected.Metrics) > 0 {
		b.WriteString("\n## Metrics\n\n| Name | Type | Unit | Description |\n|---|---|---|---|\n")
		for _, metric := range d.DataCollected.Metrics {
			fmt.Fprintf(&b, "| `%s` | %s | %s | %s |\n", metric.Name, metric.Type, escape(metric.Unit), escape(metric.Description))
		}
	}
	return b.String(), nil
}

func escape(s string) string {
	s = strings.ReplaceAll(s, "|", `\|`)
	return strings.ReplaceAll(s, "\n", " ")
}
